import{_ as e,o as i,a as r,b as s}from"./app.DKoEZOcr.js";const a="/ascendc.github.io/pr/5487/assets/op_opt_flow.BLBM9kJN.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"本文档组织结构","link":"/guide/operator_practice/document_structure"}]},"headers":[],"relativePath":"guide/operator_practice/document_structure.md","filePath":"guide/operator_practice/document_structure.md","outlineHeaders":[{"level":2,"title":"需要具备的知识","slug":"需要具备的知识","link":"#需要具备的知识"},{"level":2,"title":"可以解决的问题","slug":"可以解决的问题","link":"#可以解决的问题"}],"lastUpdated":1787050286000}'),o={name:"guide/operator_practice/document_structure.md"};function n(l,t,p,_,c,d){return i(),r("div",null,[...t[0]||(t[0]=[s('<div><article class="markdown-body"><h1>本文档组织结构<span id="ZH-CN_TOPIC_0000001846719812"></span></h1><h2 id="需要具备的知识">需要具备的知识<span id="section9155515143412"></span><a class="header-anchor" href="#需要具备的知识">​</a></h2><p>本文档主要用于指导开发者基于Ascend C编程语言在昇腾AI处理器上开发高性能的算子。在阅读此文档时，需要开发者具备如下能力：</p><ul><li>熟练使用C++编程语言。</li><li>了解计算机架构。</li><li>理解昇腾AI处理器硬件架构。</li><li>完成Ascend C编程相关文档、课程学习。</li><li>可以完成Ascend C开发、调试环境搭建。</li><li>可以独立完成Ascend C算子的开发。</li><li>熟练使用性能分析工具获取性能数据。</li></ul><p>您可以通过<a href="https://www.hiascend.com/zh/ascend-c">LINK</a>获取如上内容的学习资料。</p><h2 id="可以解决的问题">可以解决的问题<span id="section235444416411"></span><a class="header-anchor" href="#可以解决的问题">​</a></h2><p>开发者完成Ascend C算子（本文后续提到的算子均指使用Ascend C开发的算子）的开发后，如果需要对算子性能进行进一步优化，那么通过阅读本文档可以得到有效帮助。</p><p>本文档首先介绍异构计算的硬件特点及运行的数据交互，然后介绍使用Ascend C编程时调试调优的思路以及各种性能优化手段，最后介绍具体的性能优化案例。</p><p>优化算子性能是一个持续迭代的流程，将如下步骤不断循环迭代，直至达成性能目标。在<a href="best_practices/best_practices.html">优秀实践</a>章节，开发者可以进一步了解基于以下四个步骤的具体实践。</p><p><strong>图1</strong> 算子性能优化流程<span id="fig2643134112816"></span><br><img src="'+a+'" alt title="算子性能优化流程"></p><p>本文档分为如下几个章节，各章的内容以及目标如下：</p><ul><li><strong><a href="heterogeneous_computing.html">异构计算</a></strong>：介绍算子在硬件上的部署以及运行的数据流。目的是让开发者在宏观上了解硬件架构上可能影响算子执行性能的流程。</li><li><strong><a href="simd_operator_impl/overview.html">SIMD算子实现</a></strong>：介绍矢量编程、矩阵编程、融合算子编程三种典型场景下的算子Tiling、核函数（Kernel）实现，是对Ascend C编程范式的具体应用。</li><li><strong><a href="simt_operator_impl/simt_operator_impl.html">SIMT算子实现</a></strong>：介绍使用SIMT API进行算子开发的参考案例。</li><li><strong><a href="simd_simt_hybrid_operator_impl/simd_simt_hybrid_operator_impl.html">SIMD与SIMT混合算子实现</a></strong>：介绍使用Reg矢量计算API和SIMT API进行SIMD与SIMT混合编程的算子开发参考案例。</li><li><strong><a href="functional_debug/functional_debug.html">功能调试</a></strong>：介绍部分比较常见的影响算子功能的场景。目的是让开发者可以快速解决功能问题，便于进行性能优化，以及快速解决在性能优化过程中可能出现的功能问题。</li><li><strong><a href="performance_analysis/performance_analysis.html">性能分析</a></strong>：介绍了算子性能数据分析的方向。目的是让开发者能够通过分析性能数据，识别性能的优化方向。算子性能数据的测试方法，以及性能工具使用方式的详细说明请参考<a href="https://gitcode.com/Ascend/msopprof/blob/master/docs/zh/user_guide/msopprof_user_guide.md">《msOpProf用户指南》</a>，本章不做赘述。</li><li><strong><a href="simd_operator_optimization/simd_operator_optimization.html">SIMD算子性能优化</a></strong>：介绍性能优化的手段。目的是让开发者结合算子性能瓶颈点，开展性能优化工作。将主要的优化建议分成搬运优化、内存优化、API使用优化、流水优化以及Tiling优化。有一些优化建议是对上述分类的综合体现，则写在了相关性比较大的章节。这些建议按优先级进行分类，优先级是综合考虑性能效果及其范围来设定：为大多数Ascend C算子带来性能收益的建议具有最高优先级，而仅影响特定情况的手段被给予较低优先级。开发者不必熟悉所有优化手段，可以根据分析得到的算子性能瓶颈，获取对应的优化手段，逐渐了解优化策略全貌。</li><li><strong><a href="simd_simt_hybrid_optimization/simd_simt_hybrid_optimization.html">SIMD与SIMT混合算子性能优化</a></strong>：介绍SIMD与SIMT混合编程场景的性能优化建议。包括内存访问优化、计算优化等。</li><li><strong><a href="simt_operator_optimization/simt_operator_optimization.html">SIMT算子性能优化</a></strong>：介绍SIMT算子的性能优化建议，当前包含内存访问和执行配置两类优化内容。</li><li><strong><a href="best_practices/best_practices.html">优秀实践</a></strong>：介绍算子性能优化的优秀实践案例。目的是让开发者结合实例更深入的理解上文内容，同时参考其中的优化手段和优化思路，完成算子的性能优化，实现从理论到实践的过渡。</li></ul></article></div>',1)])])}const g=e(o,[["render",n]]);export{h as __pageData,g as default};
